using System;using System.IO;using System.Diagnostics;using System.Globalization;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace IslandIntegrated {
 public sealed class VoicePackSnapshot {public string Codex="",Claude="";public string[] Packs=new string[0];public bool Available;}
 public static class VoicePackStore {
  public static string DefaultRoot {get{string configured=Environment.GetEnvironmentVariable("SIDEBAR_VOICE_HOME");if(!String.IsNullOrWhiteSpace(configured))return Path.GetFullPath(configured);return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),@".claude\hooks\peon-ping");}}
  static void Safe(string path){for(var d=new DirectoryInfo(Path.GetDirectoryName(Path.GetFullPath(path)));d!=null;d=d.Parent)if(d.Exists&&(d.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Voice configuration path is redirected");if(File.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Voice configuration is redirected");}
  static Dictionary<string,object> Config(string file,out string raw){Safe(file);var info=new FileInfo(file);if(!info.Exists||info.Length>1048576)throw new IOException("Voice configuration unavailable");raw=File.ReadAllText(file);return new JavaScriptSerializer{MaxJsonLength=1048576,RecursionLimit=24}.DeserializeObject(raw) as Dictionary<string,object>;}
  static string Str(Dictionary<string,object> d,string key){object o;return d!=null&&d.TryGetValue(key,out o)&&o is string?(string)o:"";}
  static bool PackName(string name){if(String.IsNullOrWhiteSpace(name)||name.Length>100||name=="."||name==".."||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0)return false;return name.IndexOfAny(new[]{'\\','/'})<0;}
  static string[] Packs(string root){var list=new List<string>();string dir=Path.Combine(root,"packs");Safe(Path.Combine(dir,"placeholder"));if(!Directory.Exists(dir))return list.ToArray();foreach(var p in Directory.GetDirectories(dir)){string name=Path.GetFileName(p);if(list.Count>=256)break;if(!PackName(name)||name=="peon"||(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)continue;string sounds=Path.Combine(p,"sounds");if(Directory.Exists(sounds)&&(File.GetAttributes(sounds)&FileAttributes.ReparsePoint)==0)list.Add(name);}list.Sort(StringComparer.Ordinal);return list.ToArray();}
  static object[] Rules(Dictionary<string,object> d){object value;return d.TryGetValue("ide_rules",out value)&&value is object[]?(object[])value:new object[0];}
  static string Selected(Dictionary<string,object> d,string ide,string[] packs){string s=Str(d,"default_pack");if(s==""||s=="peon")s=Str(d,"active_pack");foreach(var r in Rules(d)){var rule=r as Dictionary<string,object>;if(String.Equals(Str(rule,"ide"),ide,StringComparison.OrdinalIgnoreCase)){s=Str(rule,"pack");break;}}return Array.IndexOf(packs,s)>=0?s:"";}
  public static VoicePackSnapshot Read(string root){try{string raw;var d=Config(Path.Combine(root,"config.json"),out raw);var packs=Packs(root);return new VoicePackSnapshot{Available=d!=null&&packs.Length>0,Packs=packs,Codex=Selected(d,"codex",packs),Claude=Selected(d,"claude",packs)};}catch{return new VoicePackSnapshot();}}
  public static VoicePackSnapshot Read(){return Read(DefaultRoot);}
  public static string Label(string pack){return pack=="ae_qianyu"?"厄祈千羽":pack=="starrail-kafka-peon-pack"?"卡芙卡":String.IsNullOrEmpty(pack)?"未设置":pack;}
  // Called only by an explicit voice-chip click. Preserves unrelated fields and
  // a durable backup; never executes a pack's scripts or automatically plays audio.
  public static string SelectNext(string ide){return SelectNext(DefaultRoot,ide);}
  public static string SelectNext(string root,string ide){if(ide!="codex"&&ide!="claude")throw new ArgumentException("Unknown voice target");string file=Path.Combine(root,"config.json"),raw;var d=Config(file,out raw);var packs=Packs(root);if(d==null||packs.Length<1)throw new IOException("No local voice packs");string next=packs[(Array.IndexOf(packs,Selected(d,ide,packs))+1)%packs.Length];var rules=new List<object>(Rules(d));bool found=false;foreach(var r in rules){var rule=r as Dictionary<string,object>;if(String.Equals(Str(rule,"ide"),ide,StringComparison.OrdinalIgnoreCase)){rule["pack"]=next;found=true;}}if(!found)rules.Add(new Dictionary<string,object>{{"ide",ide},{"pack",next}});d["ide_rules"]=rules.ToArray();var text=new JavaScriptSerializer{MaxJsonLength=1048576,RecursionLimit=24}.Serialize(d);if(File.ReadAllText(file)!=raw)throw new IOException("Voice configuration changed concurrently");string tmp=file+".sidebar-"+Guid.NewGuid().ToString("N")+".tmp",backup=file+".sidebar-"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffff")+".bak";File.WriteAllText(tmp,text,new System.Text.UTF8Encoding(false));try{Safe(file);if(File.ReadAllText(file)!=raw)throw new IOException("Voice configuration changed concurrently");File.Replace(tmp,file,backup);return next;}finally{if(File.Exists(tmp))File.Delete(tmp);}}
 }
 public sealed class GpuSample {public double? Usage,UsedMb,TotalMb;}
 public static class LocalGpuSensor {
  static Process pending;static DateTime checkedAt=DateTime.MinValue;static GpuSample last=new GpuSample();static bool denied;
  public static GpuSample Parse(string line){double usage,used,total;var a=(line??"").Trim().Split(',');if(a.Length!=3||!Double.TryParse(a[0],NumberStyles.Float,CultureInfo.InvariantCulture,out usage)||!Double.TryParse(a[1],NumberStyles.Float,CultureInfo.InvariantCulture,out used)||!Double.TryParse(a[2],NumberStyles.Float,CultureInfo.InvariantCulture,out total)||Double.IsNaN(usage)||Double.IsInfinity(usage)||usage<0||usage>100||Double.IsNaN(used)||Double.IsInfinity(used)||Double.IsNaN(total)||Double.IsInfinity(total)||used<0||total<=0||used>total)return new GpuSample();return new GpuSample{Usage=usage,UsedMb=used,TotalMb=total};}
  public static GpuSample Read(){if(denied)return new GpuSample();if((DateTime.UtcNow-checkedAt).TotalSeconds<5)return last;checkedAt=DateTime.UtcNow;last=new GpuSample();try{if(pending!=null){if(!pending.HasExited)return new GpuSample();pending.Dispose();pending=null;}string exe=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"nvidia-smi.exe");if(!File.Exists(exe))return new GpuSample();var info=new ProcessStartInfo(exe,"--query-gpu=utilization.gpu,memory.used,memory.total --format=csv,noheader,nounits"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardOutput=true,RedirectStandardError=true};pending=Process.Start(info);if(!pending.WaitForExit(1200))return new GpuSample();string text=pending.StandardOutput.ReadToEnd();int code=pending.ExitCode;pending.Dispose();pending=null;last=code==0&&text.Length<=4096?Parse(text.Split('\n')[0]):new GpuSample();return last;}catch(System.ComponentModel.Win32Exception e){if(e.NativeErrorCode==5)denied=true;return new GpuSample();}catch(UnauthorizedAccessException){denied=true;return new GpuSample();}catch{return new GpuSample();}}
 }
}
